) as v(category_slug, old_slug, slug, name, description)
join public.categories c on c.slug = v.category_slug
where p.category_id = c.id
  and p.slug = v.old_slug
  and not exists (select 1 from public.products o where o.slug = v.slug and o.id <> p.id);
